// saison 6 (ZZ) — XIMGS : réserve d'images de l'appareil (IndexedDB, sans la limite de ~5 Mo du stockage local).
// Quand une photo (fond d'accueil, bannière…) ne tient plus dans le stockage local, elle part ici et le réglage garde
// une petite référence « xiiiimg:… » ; marche hors ligne, ne dépend pas du Drive.
const XIMGS = (() => {
    const db = () => new Promise((res, rej) => { const r = indexedDB.open('xiiiImg', 1); r.onupgradeneeded = () => r.result.createObjectStore('i'); r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error); });
    const tx = async (m, fn) => { const d = await db(); return new Promise((res, rej) => { const t = d.transaction('i', m), q = fn(t.objectStore('i')); t.oncomplete = () => res(q && q.result); t.onerror = () => rej(t.error); }); };
    const C = {}, is = v => typeof v === 'string' && v.indexOf('xiiiimg:') === 0;
    async function put(data) { const id = 'i' + Date.now().toString(36) + Math.random().toString(36).slice(2, 7); await tx('readwrite', s => s.put(data, id)); C[id] = data; return 'xiiiimg:' + id; }
    async function get(v) { if (!is(v)) return v || ''; const id = v.slice(8); if (C[id]) return C[id]; const d = await tx('readonly', s => s.get(id)).catch(() => null); if (d) C[id] = d; return d || ''; }
    // enregistre l'objet dans le stockage local ; s'il est plein, l'image (champ « field ») passe dans la réserve
    async function save(key, obj, field) { try { localStorage.setItem(key, JSON.stringify(obj)); return true; } catch (e) { }
        if (!obj[field] || is(obj[field])) return false; try { obj[field] = await put(obj[field]); localStorage.setItem(key, JSON.stringify(obj)); return true; } catch (e) { return false; } }
    // même chose pour une clé qui contient directement l'image
    async function saveRaw(key, data) { try { localStorage.setItem(key, data); return true; } catch (e) { } try { localStorage.setItem(key, await put(data)); return true; } catch (e) { return false; } }
    return { put, get, is, save, saveRaw };
})();

